#include "../layout.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
using namespace velocitex;
std::ifstream input("artifacts/cpp-rewrite/layout-probe.bin",std::ios::binary);
template<class T>T read(){T v{};input.read((char*)&v,sizeof(v));return v;}
std::optional<std::u16string> str(){int n=read<int>();if(n<0)return {};std::u16string s(n,0);input.read((char*)s.data(),n*2);return s;}
TexLength len(){double n=read<double>();return {n,TexUnit(read<int>())};}
struct ProbeShaper:IMathTextShaper{
 bool TryShape(int cp,MathFont,MathTextShape& s)override{double w=.7+(cp%7)*.01;s={w,{{MathPathOperation::Move,0,-.7},{MathPathOperation::Line,w,-.7},{MathPathOperation::Line,w,.2},{MathPathOperation::Line,0,.2},{MathPathOperation::Close,0,0}},{0,-.7,w,.9},u"Probe"};return true;}
 bool SupportsRuns()const override{return true;}
 bool TryShapeRun(std::u16string_view text,MathFont f,MathTextRunShape& s)override{s={};double x=0;for(size_t i=0;i<text.size();){int length,cp=scalar_at(text,i,length);i+=length;MathTextShape v;TryShape(cp,f,v);s.Paths.push_back({v.Segments,x,0,1,1,{x,-.7,v.Advance,.9}});x+=v.Advance;}s.Advance=x;s.InkBounds={0,-.7,x,.9};return true;}
};
int main(){int count=0,errors=0;while(input.peek()!=EOF){auto id=str();MathOptions o;o.DisplayMode=read<bool>();o.FontSize=read<double>();o.MaxSize=read<double>();o.MinRuleThickness=read<double>();o.DisplayWidth=read<double>();o.Leqno=read<bool>();o.Fleqn=read<bool>();o.EquationNumber=read<int>();o.StrictMode=MathStrictMode(read<int>());int n=read<int>(),root=read<int>();std::vector<SemanticNode>nodes(n);for(auto& x:nodes){x.Kind=NodeKind(read<int>());x.FirstChild=read<int>();x.NextSibling=read<int>();x.SecondChild=read<int>();x.ThirdChild=read<int>();x.FourthChild=read<int>();x.CodePoint=read<int>();x.OriginalCodePoint=read<int>();x.FontIdOverride=read<int>();x.Atom=MathAtom(read<int>());x.Font=MathFont(read<int>());x.SymbolFont=MathFont(read<int>());x.Style=MathStyle(read<int>());x.TextMode=read<bool>();x.Value=read<double>();x.Value2=read<double>();x.Value3=read<double>();x.Text=str();x.Alignment=str();x.Text2=str();x.Text3=str();x.Length1=len();x.Length2=len();x.Length3=len();x.LeftDelimiter=read<int>();x.RightDelimiter=read<int>();x.ColumnCount=read<int>();x.RuleAbove=read<int>();x.RuleBelow=read<int>();x.HasBar=read<bool>();x.Limits=read<bool>();x.AlwaysLimits=read<bool>();x.NeverLimits=read<bool>();x.IsMathOrd=read<bool>();}
int expectedCount=read<int>();std::vector<double>expected(expectedCount);input.read((char*)expected.data(),expectedCount*sizeof(double));
std::vector<double>v;auto b=[&](MathBounds r){v.insert(v.end(),{r.X,r.Y,r.Width,r.Height});};
ProbeShaper shaper;o.TextShaper=&shaper;
try{auto out=build_layout(nodes,root,o);v.insert(v.end(),{out.LogicalSize.Width,out.LogicalSize.Height,out.Baseline});b(out.InkBounds);v.push_back(double(out.Glyphs.size()));for(auto g:out.Glyphs)v.insert(v.end(),{double(g.FontId),double(g.GlyphId),double(g.CodePoint),g.X,g.Y,g.FontSize});v.push_back(double(out.Rules.size()));for(auto r:out.Rules)v.insert(v.end(),{r.X,r.Y,r.Width,r.Height});v.push_back(double(out.Paths.size()));for(auto p:out.Paths){v.insert(v.end(),{p.X,p.Y,p.ScaleX,p.ScaleY});b(p.ClipBounds);v.push_back(double(p.Segments.size()));for(auto s:p.Segments)v.insert(v.end(),{double(s.Operation),s.X1,s.Y1,s.X2,s.Y2,s.X3,s.Y3});}v.push_back(double(out.PaintCommands.size()));for(auto pc:out.PaintCommands)v.insert(v.end(),{double(pc.Kind),double(pc.Index),double(pc.StateIndex)});v.push_back(double(out.PaintStates.size()));for(auto ps:out.PaintStates){v.push_back(ps.Color?1:0);if(ps.Color){auto c=*ps.Color;v.insert(v.end(),{double(c.R),double(c.G),double(c.B),double(c.A)});}auto t=ps.Transform;v.insert(v.end(),{t.M11,t.M12,t.M21,t.M22,t.Dx,t.Dy});}
auto text=[&](std::u16string_view t){v.push_back(double(t.size()));for(char16_t c:t)v.push_back(c);};v.push_back(double(out.TextGlyphs.size()));for(auto t:out.TextGlyphs){v.insert(v.end(),{double(t.CodePoint),t.X,t.Y,t.FontSize});text(t.FontFamily);}v.push_back(double(out.TextRuns.size()));for(auto t:out.TextRuns){text(t.Text);v.insert(v.end(),{t.X,t.Y,t.FontSize,double(t.FirstPath),double(t.PathCount),t.Advance});}
bool fail=v.size()!=expected.size();size_t diff=0;for(;!fail&&diff<v.size();++diff)if(std::abs(v[diff]-expected[diff])>1e-9*std::max(1.,std::abs(expected[diff]))){fail=true;break;}if(fail){if(errors++<50)std::cout<<"FAIL "<<utf8(*id)<<" values "<<v.size()<<"/"<<expected.size()<<" index "<<diff<<(diff<v.size()?" actual "+std::to_string(v[diff]):"")<<(diff<expected.size()?" expected "+std::to_string(expected[diff]):"")<<"\n";}}
catch(const CompileFailure& e){if(errors++<50)std::cout<<"FAIL "<<utf8(*id)<<" threw "<<utf8(e.Diagnostic.Message)<<"\n";}count++;}std::cout<<"Compared "<<count<<" layouts; failures "<<errors<<"\n";return errors?1:0;}
